import { defineConfig } from 'vite'

// Workaround: lightningcss minifier chokes on some pseudo-element CSS
// generated by Slidev's client styles (e.g. ::marker rules).
export default defineConfig({
  build: {
    cssMinify: 'esbuild',
  },
  server: {
    // Decks often symlink a shared diagrams folder in as ./diagrams (it lives
    // in the parent repo); allow the dev server to serve modules through it.
    fs: {
      allow: ['..'],
    },
  },
})
